fn min_inspectors(n: i8, d: i8) -> i8 {
    // Each inspector covers up to a block of length (2*d + 1).
    let coverage = 2 * d + 1;
    // The minimum number of inspectors is the ceiling of n / coverage.
    // In integer arithmetic, ceil(a/b) = (a + b - 1) / b for positive a, b.
    (n + coverage - 1) / coverage
}

